package org.securemail.community.http;

import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.securemail.community.core.*;
import org.securemail.community.access.AccessControl;
import org.securemail.community.org.OrgAdminService;
import org.securemail.community.content.ContentService;
import org.securemail.community.agent.AgentService;
import org.securemail.community.protocol.CommunityAuth;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Path;
import java.security.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;

/** Real loopback HTTP, Ed25519 and SQLite; neither Tor nor a native-client acceptance claim. */
class CommunityHttpServerTest {
 @TempDir Path dir;
 private final Clock clock=Clock.fixed(Instant.ofEpochMilli(1_800_000_000_000L),ZoneOffset.UTC);
 CommunityStore store;AccessControl access;ContentService content;AgentService agent;CommunityHttpServer server;KeyPair service,user;
 @BeforeEach void setup()throws Exception {service=key();user=key();store=new CommunityStore(dir.resolve("community.sqlite"),clock);byte[]kek=new byte[32];new SecureRandom().nextBytes(kek);access=new AccessControl(store,kek);content=new ContentService(store,access);store.setNotificationSink(content::notifyAccount);agent=new AgentService(store,access,content::ingestAi);server=new CommunityHttpServer(new InetSocketAddress(InetAddress.getLoopbackAddress(),0),store,access,new OrgAdminService(store,access,clock),content,agent,service);server.start();}
 @AfterEach void close()throws Exception {server.close();agent.close();store.close();}
 private static KeyPair key()throws Exception{return KeyPairGenerator.getInstance("Ed25519").generateKeyPair();}
 private byte[] body(String action,Map<String,Object> data){return StrictJson.bytes(Map.of("action",action,"data",data));}
 private record Response(int status,Map<String,String> headers,byte[] exact,Map<String,Object> document){}
 private Response send(KeyPair caller,byte[] body,long time,String nonce,String audience,byte[] transmitted,Map<String,String> extras)throws Exception {
   byte[] signature=CommunityAuth.sign(caller.getPrivate(),CommunityAuth.requestBytes(audience,time,nonce,body));
   Map<String,String> headers=new LinkedHashMap<>(Map.of("Host","localhost","Connection","close","Content-Type","application/json; charset=utf-8","Content-Length",Integer.toString(transmitted.length),"AEGIS-Key",Base64.getEncoder().encodeToString(caller.getPublic().getEncoded()),"AEGIS-Time",Long.toString(time),"AEGIS-Nonce",nonce,"AEGIS-Signature",Base64.getEncoder().encodeToString(signature)));headers.putAll(extras);
   try(var socket=new Socket(InetAddress.getLoopbackAddress(),server.port())){socket.setSoTimeout(10000);var out=socket.getOutputStream();StringBuilder request=new StringBuilder("POST /api/v1 HTTP/1.1\r\n");headers.forEach((k,v)->request.append(k).append(": ").append(v).append("\r\n"));out.write(request.append("\r\n").toString().getBytes(StandardCharsets.US_ASCII));out.write(transmitted);out.flush();var in=new BufferedInputStream(socket.getInputStream());String status=line(in);Map<String,String> responseHeaders=new TreeMap<>(String.CASE_INSENSITIVE_ORDER);String value;while(!(value=line(in)).isEmpty()){int colon=value.indexOf(':');responseHeaders.put(value.substring(0,colon),value.substring(colon+1).strip());}int length=Integer.parseInt(responseHeaders.get("Content-Length"));assertTrue(length<=CommunityAuth.MAX_BODY);byte[] exact=in.readNBytes(length);assertEquals(length,exact.length);assertTrue(CommunityAuth.verify(service.getPublic().getEncoded(),CommunityAuth.responseBytes(CommunityAuth.id(service.getPublic().getEncoded()),nonce,exact),Base64.getDecoder().decode(responseHeaders.get("AEGIS-Signature"))),"Every response must authenticate its exact body and original nonce");return new Response(Integer.parseInt(status.split(" ")[1]),responseHeaders,exact,StrictJson.object(exact,CommunityAuth.MAX_BODY));}
 }
 private Response call(String action,Map<String,Object> data)throws Exception {byte[] bytes=body(action,data);return send(user,bytes,clock.millis(),CommunityAuth.nonce(),CommunityAuth.id(service.getPublic().getEncoded()),bytes,Map.of());}
 private static String line(InputStream in)throws IOException {var bytes=new ByteArrayOutputStream();int previous=-1;for(int n=0;n<8192;n++){int b=in.read();if(b<0)throw new EOFException();if(previous=='\r'&&b=='\n'){byte[] all=bytes.toByteArray();return new String(all,0,all.length-1,StandardCharsets.US_ASCII);}bytes.write(b);previous=b;}throw new IOException("Header limit");}
 @SuppressWarnings("unchecked") private static Map<String,Object> data(Response response){assertEquals(true,response.document.get("ok"));return(Map<String,Object>)response.document.get("data");}
 @SuppressWarnings("unchecked") private static String code(Response response){assertEquals(false,response.document.get("ok"));return(String)((Map<String,Object>)response.document.get("error")).get("code");}
 @Test void signedCapabilityAliasRegistersOnlyItsAuthenticatedIdentity()throws Exception {Response response=call("session.capabilities",Map.of());assertEquals(200,response.status);assertEquals(CommunityAuth.id(user.getPublic().getEncoded()),data(response).get("identity"));assertEquals(false,data(response).get("isAdmin"));assertNotNull(response.document.get("authorizationEpoch"));assertEquals("no-store",response.headers.get("Cache-Control"));assertEquals(1L,store.tx(db->CommunityStore.count(db,"identities")).longValue());}
 @Test void bodyTamperingIsRejectedBeforeJsonParsingOrIdentityRegistration()throws Exception {byte[] bytes=body("community.me",Map.of()),broken="{not-json".getBytes(StandardCharsets.UTF_8);Response rejected=send(user,bytes,clock.millis(),CommunityAuth.nonce(),CommunityAuth.id(service.getPublic().getEncoded()),broken,Map.of());assertEquals(401,rejected.status);assertEquals("AUTH",code(rejected));assertEquals(0L,store.tx(db->CommunityStore.count(db,"identities")).longValue());}
 @Test void audienceTimestampAndReplayAreEnforcedAcrossHttpRequests()throws Exception {byte[] bytes=body("community.me",Map.of());String nonce=CommunityAuth.nonce(),audience=CommunityAuth.id(service.getPublic().getEncoded());assertEquals(200,send(user,bytes,clock.millis(),nonce,audience,bytes,Map.of()).status);assertEquals("REPLAY",code(send(user,bytes,clock.millis(),nonce,audience,bytes,Map.of())));assertEquals("AUTH",code(send(user,bytes,clock.millis()-60001,CommunityAuth.nonce(),audience,bytes,Map.of())));assertEquals("AUTH",code(send(user,bytes,clock.millis()+60001,CommunityAuth.nonce(),audience,bytes,Map.of())));assertEquals("AUTH",code(send(user,bytes,clock.millis(),CommunityAuth.nonce(),"f".repeat(64),bytes,Map.of())));}
 @Test void duplicateKeysDepthAndMalformedUtf8AreRejectedAfterSignatureAndNonceConsumption()throws Exception {String audience=CommunityAuth.id(service.getPublic().getEncoded());List<byte[]> bad=List.of("{\"action\":\"community.me\",\"action\":\"admin.audit\",\"data\":{}}".getBytes(StandardCharsets.UTF_8),"{\"action\":\"community.me\",\"data\":{\"x\":".concat("[".repeat(20)).concat("0").concat("]".repeat(20)).concat("}}").getBytes(StandardCharsets.UTF_8),new byte[]{'{','"','x','"',':','"',(byte)0xc3,0x28,'"','}'},"{\"action\":\"community.me\",\"data\":{\"payload\":1e2147483647}}".getBytes(StandardCharsets.UTF_8),"{\"action\":\"community.me\",\"data\":{\"payload\":1e-2147483647}}".getBytes(StandardCharsets.UTF_8),"{\"action\":\"community.me\",\"data\":{\"payload\":1١}}".getBytes(StandardCharsets.UTF_8),("{\"action\":\"community.me\",\"data\":{\"payload\":\""+"\\"+"u+001\"}}").getBytes(StandardCharsets.UTF_8),("{\"action\":\"community.me\",\"data\":{\"payload\":\""+"\\"+"u٠٠٤١\"}}").getBytes(StandardCharsets.UTF_8));for(byte[] bytes:bad){String nonce=CommunityAuth.nonce();assertEquals("INVALID",code(send(user,bytes,clock.millis(),nonce,audience,bytes,Map.of())));assertEquals("REPLAY",code(send(user,bytes,clock.millis(),nonce,audience,bytes,Map.of())));}}
 @Test void oversizedAndEncodedRequestsNeverReachBusinessHandlers()throws Exception {byte[] bytes=body("community.me",Map.of());String audience=CommunityAuth.id(service.getPublic().getEncoded());Response huge=send(user,bytes,clock.millis(),CommunityAuth.nonce(),audience,new byte[0],Map.of("Content-Length",Integer.toString(CommunityAuth.MAX_BODY+1)));assertEquals(413,huge.status);assertEquals("LIMIT",code(huge));assertEquals("INVALID",code(send(user,bytes,clock.millis(),CommunityAuth.nonce(),audience,bytes,Map.of("Content-Encoding","gzip"))));assertEquals(0L,store.tx(db->CommunityStore.count(db,"identities")).longValue());}
 @Test void closedAndMissingMaterialsHaveTheSameSignedErrorAndCannotLeakThroughGraph()throws Exception {
   String actor=store.ensureIdentity(user.getPublic().getEncoded(),"Участник"),owner=store.ensureIdentity(key().getPublic().getEncoded(),"Редактор");String role=UUID.randomUUID().toString();store.tx(db->{try(var q=db.prepareStatement("INSERT INTO roles(id,scope,name) VALUES(?,'GLOBAL',?)")){q.setString(1,role);q.setString(2,role);q.executeUpdate();}for(String p:Set.of("LIBRARY_CREATE","LIBRARY_PUBLISH","LIBRARY_ACCESS_MANAGE"))try(var q=db.prepareStatement("INSERT INTO role_permissions VALUES(?,?)")){q.setString(1,role);q.setString(2,p);q.executeUpdate();}try(var q=db.prepareStatement("INSERT INTO assignments VALUES(?,?)")){q.setString(1,owner);q.setString(2,role);q.executeUpdate();}return null;});
   Map<String,Object> material=content.handle(owner,"content.library.create",Map.of("title","Закрытое название","body","Приватный текст","policy",Map.of("users",List.of(owner))));content.handle(owner,"content.library.publish",Map.of("id",material.get("id"),"revision",1));
   Response closed=call("content.library.get",Map.of("id",material.get("id"))),missing=call("content.library.get",Map.of("id",UUID.randomUUID().toString()));assertEquals("NOT_FOUND",code(closed));assertEquals(code(closed),code(missing));assertEquals(closed.document.get("error"),missing.document.get("error"));assertTrue(((List<?>)data(call("content.library.graph",Map.of())).get("nodes")).isEmpty());assertFalse(new String(closed.exact,StandardCharsets.UTF_8).contains("Закрытое название"));
 }
 @Test void concurrentReplayCommitsExactlyOneNonce()throws Exception {byte[] bytes=body("community.me",Map.of());String nonce=CommunityAuth.nonce(),audience=CommunityAuth.id(service.getPublic().getEncoded());var pool=Executors.newFixedThreadPool(2);try{Callable<Response> task=()->send(user,bytes,clock.millis(),nonce,audience,bytes,Map.of());List<Future<Response>> results=pool.invokeAll(List.of(task,task));Set<Integer> statuses=Set.of(results.get(0).get().status,results.get(1).get().status);assertEquals(Set.of(200,409),statuses);}finally{pool.shutdownNow();}}
 @Test void publicBindIsRejectedAndNoGetEndpointExposesKeysOrAdministration()throws Exception {assertThrows(IOException.class,()->new CommunityHttpServer(new InetSocketAddress("0.0.0.0",0),store,access,new OrgAdminService(store,access,clock),content,agent,service));try(var socket=new Socket(InetAddress.getLoopbackAddress(),server.port())){socket.setSoTimeout(3000);socket.getOutputStream().write("GET /api/v1 HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n\r\n".getBytes(StandardCharsets.US_ASCII));String response=new String(socket.getInputStream().readNBytes(1024),StandardCharsets.UTF_8);assertTrue(response.startsWith("HTTP/1.1 404"));assertFalse(response.contains(Base64.getEncoder().encodeToString(service.getPublic().getEncoded())));}}
 @Test void registeredWorkerCannotUseHumanOrContentEndpointsEvenWithMisconfiguredExtraRole()throws Exception {
   String actor=store.ensureIdentity(user.getPublic().getEncoded(),"Рабочий узел"),role=UUID.randomUUID().toString();store.tx(db->{try(var q=db.prepareStatement("INSERT INTO roles(id,scope,name) VALUES(?,'GLOBAL',?)")){q.setString(1,role);q.setString(2,role);q.executeUpdate();}for(String permission:List.of("AGENT_WORK","LIBRARY_READ"))try(var q=db.prepareStatement("INSERT INTO role_permissions VALUES(?,?)")){q.setString(1,role);q.setString(2,permission);q.executeUpdate();}try(var q=db.prepareStatement("INSERT INTO assignments VALUES(?,?)")){q.setString(1,actor);q.setString(2,role);q.executeUpdate();}try(var q=db.prepareStatement("INSERT INTO agent_worker(identity,enabled,last_seen) VALUES(?,1,0)")){q.setString(1,actor);q.executeUpdate();}return null;});
   assertEquals("DENIED",code(call("community.me",Map.of())));assertEquals("DENIED",code(call("content.library.graph",Map.of())));assertEquals("DENIED",code(call("agent.worker.claim",Map.of())));store.tx(db->{try(var q=db.prepareStatement("DELETE FROM role_permissions WHERE role=? AND permission='LIBRARY_READ'")){q.setString(1,role);q.executeUpdate();}return null;});assertEquals(200,call("agent.worker.claim",Map.of()).status);
 }
 @Test void httpOriginCannotRebindDatabaseToAnotherServiceIdentity()throws Exception {assertThrows(IOException.class,()->new CommunityHttpServer(new InetSocketAddress("127.0.0.1",0),store,access,new OrgAdminService(store,access,clock),content,agent,key()));assertEquals(CommunityAuth.id(service.getPublic().getEncoded()),server.serviceFingerprint());assertEquals(200,call("community.me",Map.of()).status);}
 @Test void responseAlsoBindsAuthenticatedActorAndExactRequestAgainstSameNonceSubstitution()throws Exception {
   String nonce=CommunityAuth.nonce(),audience=CommunityAuth.id(service.getPublic().getEncoded());byte[] first=body("community.me",Map.of()),second=body("content.library.graph",Map.of());KeyPair other=key();Response victim=send(user,first,clock.millis(),nonce,audience,first,Map.of()),substitute=send(other,second,clock.millis(),nonce,audience,second,Map.of());
   assertEquals(200,victim.status);assertEquals(200,substitute.status);assertEquals(CommunityAuth.id(user.getPublic().getEncoded()),victim.document.get("requestIdentity"));assertEquals(CommunityAuth.id(CommunityAuth.requestBytes(audience,clock.millis(),nonce,first)),victim.document.get("requestSha256"));assertNotEquals(victim.document.get("requestIdentity"),substitute.document.get("requestIdentity"));assertNotEquals(victim.document.get("requestSha256"),substitute.document.get("requestSha256"));
 }
 @Test void underscoreVoiceBatchActionReachesAuthoritativeHandler()throws Exception {String peer=store.ensureIdentity(key().getPublic().getEncoded(),"Другой контакт");Response response=call("org.calls.authorize_batch",Map.of("targets",List.of(peer),"direction","INCOMING"));assertEquals(200,response.status);assertEquals(1,((List<?>)data(response).get("decisions")).size());assertNotNull(data(response).get("expires"));}
 @Test void largeButBoundedAttachmentStringParsesWhileCollectionBombDoesNot()throws Exception {String base64="A".repeat(200000);Map<String,Object> parsed=StrictJson.object(StrictJson.bytes(Map.of("action","content.files.upload","data",Map.of("base64",base64))),CommunityAuth.MAX_BODY);assertNotNull(parsed.get("data"));assertThrows(IOException.class,()->StrictJson.object(("{\"x\":["+"0,".repeat(9000)+"0]}").getBytes(StandardCharsets.UTF_8),CommunityAuth.MAX_BODY));}
}
